def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    def mode(seq):
        return Counter(seq).most_common(1)[0][0]

    candidates = []
    for color in counts:
        if color == background:
            continue
        rows = [r for r in range(h) if mode(grid[r]) == color]
        cols = [c for c in range(w) if mode([grid[r][c] for r in range(h)]) == color]
        if len(rows) >= 2 and len(cols) >= 2:
            candidates.append((len(rows) + len(cols), color, rows, cols))
    if not candidates:
        return [row[:] for row in grid]
    _, line_color, rows, cols = max(candidates)

    # Each output pixel is represented by a same-colored 2x2 set of grid
    # intersections. Inconsistent blocks are empty/background.
    decoded = []
    for i in range(len(rows) - 1):
        row = []
        for j in range(len(cols) - 1):
            vals = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                    grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            if vals[0] == vals[1] == vals[2] == vals[3] and vals[0] not in (background, line_color):
                row.append(vals[0])
            else:
                row.append(background)
        decoded.append(row)

    points = [(r, c) for r, row in enumerate(decoded) for c, v in enumerate(row)
              if v != background]
    if not points:
        return [[background]]
    r0, r1 = min(r for r, _ in points), max(r for r, _ in points)
    c0, c1 = min(c for _, c in points), max(c for _, c in points)
    return [row[c0:c1 + 1] for row in decoded[r0:r1 + 1]]
